// Generated by the website's scripts/build-peppol-ubl-check.ts from its own copy of these tests; edit there.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { validateInvoiceXml, type ValidationProfile } from "../src/engine/validate";


/** The website's sample invoices, as written to test/fixtures/. */
const SAMPLES: Record<string, string> = {
  "peppol-valid": "valid/peppol-bis3-valid-be.xml",
  "credit-note-valid": "valid/peppol-credit-note.xml",
  "reverse-charge-valid": "valid/reverse-charge-de-nl.xml",
  "vat-calculation-error": "invalid/invalid-vat-calculation.xml",
  "missing-mandatory": "invalid/missing-mandatory-fields.xml",
  "be-endpoint-errors": "invalid/be-endpoint-errors.xml",
  "malformed-xml": "invalid/malformed.xml",
  "de-xrechnung-ubl-valid": "xrechnung/xrechnung-ubl-valid.xml",
  "de-xrechnung-cii-valid": "xrechnung/xrechnung-cii-valid.xml",
  "de-xrechnung-ubl-errors": "xrechnung/xrechnung-ubl-errors.xml",
  "de-xrechnung-cii-errors": "xrechnung/xrechnung-cii-errors.xml",
  "nl-si-ubl-valid": "nlcius/si-ubl-valid.xml",
  "nl-si-ubl-errors": "nlcius/si-ubl-errors.xml",
  "factur-x-en16931": "factur-x/factur-x-en16931.xml"
};
const getSample = (id: string) =>
  SAMPLES[id] ? { content: readFileSync(resolve(__dirname, "fixtures", SAMPLES[id]!), "utf8") } : undefined;

/**
 * Official verdicts beyond the calculation margins, held to the rule sets the checker follows:
 * Peppol BIS Billing 3.0.22 (PEPPOL-EN16931-UBL.sch and -CII.sch) and the CEN EN 16931 rules
 * 1.3.17. The Peppol unit tests may not be redistributed, so each case here restates one of them
 * (the file it comes from is named) in our own minimal invoice; the CEN cases are vendored in
 * src/test/fixtures/en16931-cen and run by official-margins.test.ts.
 */

const UBL_NS =
  'xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2" xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2"';
const ubl = (body: string, root: "Invoice" | "CreditNote" = "Invoice") =>
  `<?xml version="1.0" encoding="UTF-8"?>\n<${root} xmlns="urn:oasis:names:specification:ubl:schema:xsd:${root}-2" ${UBL_NS}>${body}</${root}>`;
const cii = (body: string) =>
  `<?xml version="1.0" encoding="UTF-8"?>\n<rsm:CrossIndustryInvoice xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100">${body}</rsm:CrossIndustryInvoice>`;
const PEPPOL_CID = "urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0";
const PEPPOL_PROFILE = "urn:fdc:peppol.eu:2017:poacc:billing:01:1.0";
const ciiContext = (cid = PEPPOL_CID, profile: string | null = PEPPOL_PROFILE) =>
  `<rsm:ExchangedDocumentContext>${profile === null ? "" : `<ram:BusinessProcessSpecifiedDocumentContextParameter><ram:ID>${profile}</ram:ID></ram:BusinessProcessSpecifiedDocumentContextParameter>`}<ram:GuidelineSpecifiedDocumentContextParameter><ram:ID>${cid}</ram:ID></ram:GuidelineSpecifiedDocumentContextParameter></rsm:ExchangedDocumentContext>`;
const ciiTx = (parts: { agreement?: string; delivery?: string; settlement?: string; lines?: string }) =>
  `<rsm:SupplyChainTradeTransaction>${parts.lines ?? ""}<ram:ApplicableHeaderTradeAgreement>${parts.agreement ?? ""}</ram:ApplicableHeaderTradeAgreement><ram:ApplicableHeaderTradeDelivery>${parts.delivery ?? ""}</ram:ApplicableHeaderTradeDelivery><ram:ApplicableHeaderTradeSettlement>${parts.settlement ?? ""}</ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction>`;

type Verdict = "error" | "warning" | "success";
/** How the checker answers for one rule: its worst finding (info doesn't count). */
function verdict(xml: string, rule: string, profile: ValidationProfile = "peppol"): Verdict {
  const own = validateInvoiceXml(xml, profile).findings.filter((f) => f.ruleId === rule && f.severity !== "info");
  return own.some((f) => f.severity === "error") ? "error" : own.length ? "warning" : "success";
}

describe("Peppol BIS 3.0 on UBL: element presence, as the official rules test it", () => {
  it("R001 accepts an empty ProfileID element (PEPPOL-EN16931-R001.xml); R008 reports the emptiness", () => {
    const xml = ubl("<cbc:ProfileID/>");
    expect(verdict(xml, "PEPPOL-EN16931-R001")).toBe("success");
    expect(verdict(xml, "PEPPOL-EN16931-R008")).toBe("error");
  });
  it("a missing ProfileID breaks R001 and R007 (the official $profile is then 'Unknown')", () => {
    const xml = ubl(`<cbc:CustomizationID>${PEPPOL_CID}</cbc:CustomizationID>`);
    expect(verdict(xml, "PEPPOL-EN16931-R001")).toBe("error");
    expect(verdict(xml, "PEPPOL-EN16931-R007")).toBe("error");
  });
  it("R003 accepts an empty buyer reference or order reference ID (PEPPOL-EN16931-R003.xml)", () => {
    expect(verdict(ubl("<cbc:BuyerReference/>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(ubl("<cac:OrderReference><cbc:ID/></cac:OrderReference>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(ubl("<cac:OrderReference><cbc:SalesOrderID>1</cbc:SalesOrderID></cac:OrderReference>"), "PEPPOL-EN16931-R003")).toBe("error");
  });
  it("R061 accepts an empty mandate ID and needs the element for codes 49 and 59 (PEPPOL-EN16931-R061.xml)", () => {
    const pm = (code: string, mandate: string) => ubl(`<cac:PaymentMeans><cbc:PaymentMeansCode>${code}</cbc:PaymentMeansCode>${mandate}</cac:PaymentMeans>`);
    expect(verdict(pm("49", "<cac:PaymentMandate><cbc:ID/></cac:PaymentMandate>"), "PEPPOL-EN16931-R061")).toBe("success");
    expect(verdict(pm("59", "<cac:PaymentMandate><cbc:ID>M-1</cbc:ID></cac:PaymentMandate>"), "PEPPOL-EN16931-R061")).toBe("success");
    expect(verdict(pm("59", ""), "PEPPOL-EN16931-R061")).toBe("error");
    expect(verdict(pm("30", ""), "PEPPOL-EN16931-R061")).toBe("success");
  });
});

describe("Peppol BIS 3.0 on UBL: values and code lists", () => {
  it("R043 checks line-level allowances and charges too (PEPPOL-EN16931-R043.xml)", () => {
    const line = (tag: string, ind: string) => `<cac:${tag}><cac:AllowanceCharge><cbc:ChargeIndicator>${ind}</cbc:ChargeIndicator></cac:AllowanceCharge></cac:${tag}>`;
    expect(verdict(ubl(line("InvoiceLine", "0")), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(ubl(line("CreditNoteLine", "0"), "CreditNote"), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(ubl(line("InvoiceLine", "false")), "PEPPOL-EN16931-R043")).toBe("success");
    expect(verdict(ubl("<cac:AllowanceCharge><cbc:ChargeIndicator>TRUE</cbc:ChargeIndicator></cac:AllowanceCharge>"), "PEPPOL-EN16931-R043")).toBe("error");
  });
  it("R044 accepts only the literal 'false' on price level (PEPPOL-EN16931-R044.xml)", () => {
    const price = (ind: string) => ubl(`<cac:InvoiceLine><cac:Price><cac:AllowanceCharge><cbc:ChargeIndicator>${ind}</cbc:ChargeIndicator></cac:AllowanceCharge></cac:Price></cac:InvoiceLine>`);
    expect(verdict(price("0"), "PEPPOL-EN16931-R044")).toBe("error");
    expect(verdict(price("true"), "PEPPOL-EN16931-R044")).toBe("error");
    expect(verdict(price("false"), "PEPPOL-EN16931-R044")).toBe("success");
  });
  it("R051 covers every listed amount, including the line price (PEPPOL-EN16931-R051.xml)", () => {
    const doc = (price: string) =>
      ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount></cac:TaxSubtotal></cac:TaxTotal><cac:InvoiceLine><cbc:LineExtensionAmount currencyID="EUR">100</cbc:LineExtensionAmount><cac:Price>${price}</cac:Price></cac:InvoiceLine>`);
    expect(verdict(doc('<cbc:PriceAmount currencyID="NOK">100</cbc:PriceAmount>'), "PEPPOL-EN16931-R051")).toBe("error");
    expect(verdict(doc('<cbc:PriceAmount currencyID="EUR">100</cbc:PriceAmount><cac:AllowanceCharge><cbc:ChargeIndicator>false</cbc:ChargeIndicator><cbc:Amount currencyID="SEK">1</cbc:Amount></cac:AllowanceCharge>'), "PEPPOL-EN16931-R051")).toBe("error");
    expect(verdict(doc('<cbc:PriceAmount currencyID="EUR">100</cbc:PriceAmount>'), "PEPPOL-EN16931-R051")).toBe("success");
  });
  it("R051 leaves the VAT total in the accounting currency (a TaxTotal without subtotals) alone", () => {
    const xml = ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount></cac:TaxSubtotal></cac:TaxTotal><cac:TaxTotal><cbc:TaxAmount currencyID="SEK">110</cbc:TaxAmount></cac:TaxTotal>`);
    expect(verdict(xml, "PEPPOL-EN16931-R051")).toBe("success");
  });
  it("R053 needs exactly one TaxTotal with subtotals, so none fails as well (PEPPOL-EN16931-R053.xml)", () => {
    const tt = '<cac:TaxTotal><cbc:TaxAmount currencyID="EUR">10</cbc:TaxAmount><cac:TaxSubtotal/></cac:TaxTotal>';
    expect(verdict(ubl(""), "PEPPOL-EN16931-R053")).toBe("error");
    expect(verdict(ubl(tt), "PEPPOL-EN16931-R053")).toBe("success");
    expect(verdict(ubl(tt + tt), "PEPPOL-EN16931-R053")).toBe("error");
  });
  it("P0100 and P0101 only apply under an approved business process (PEPPOL-EN16931-P0100.xml, -P0101.xml)", () => {
    const inv = (profile: string) => ubl(`<cbc:ProfileID>${profile}</cbc:ProfileID><cbc:InvoiceTypeCode>999</cbc:InvoiceTypeCode>`);
    const cn = (profile: string) => ubl(`<cbc:ProfileID>${profile}</cbc:ProfileID><cbc:CreditNoteTypeCode>380</cbc:CreditNoteTypeCode>`, "CreditNote");
    expect(verdict(inv("urn:www.cenbii.eu:profile:bii04:ver1.0"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(inv(PEPPOL_PROFILE), "PEPPOL-EN16931-P0100")).toBe("error");
    expect(verdict(cn("urn:www.cenbii.eu:profile:bii04:ver1.0"), "PEPPOL-EN16931-P0101")).toBe("success");
    expect(verdict(cn("urn:peppol:bis:billing_with_response"), "PEPPOL-EN16931-P0101")).toBe("error");
  });
  it("CL008 checks every EndpointID with a schemeID, wherever it sits (PEPPOL-COMMON-EAS.xml)", () => {
    const xml = (scheme: string) => ubl(`<cac:AccountingSellerParty><cac:Party><cbc:EndpointID schemeID="${scheme}">1234567890</cbc:EndpointID></cac:Party></cac:AccountingSellerParty>`);
    expect(verdict(xml("0207"), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(xml("0007"), "PEPPOL-EN16931-CL008")).toBe("success");
  });
  it("COMMON-R043 checks 0208 numbers of every party, not only seller and buyer", () => {
    const xml = (id: string) => ubl(`<cac:PayeeParty><cac:PartyIdentification><cbc:ID schemeID="0208">${id}</cbc:ID></cac:PartyIdentification></cac:PayeeParty>`);
    expect(verdict(xml("0403.170.701"), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(xml("0403170701"), "PEPPOL-COMMON-R043")).toBe("success");
  });
  it("COMMON-R040 (GLN) is a Peppol rule: EN 16931 alone doesn't check the GS1 check digit", () => {
    const xml = ubl('<cac:AccountingSupplierParty><cac:Party><cbc:EndpointID schemeID="0088">5790000435950</cbc:EndpointID></cac:Party></cac:AccountingSupplierParty>');
    expect(verdict(xml, "PEPPOL-COMMON-R040")).toBe("error");
    expect(verdict(xml, "PEPPOL-COMMON-R040", "en16931")).toBe("success");
  });
});

describe("Peppol BIS 3.0 on CII (OpenPeppol's PEPPOL-EN16931-CII.sch)", () => {
  it("a CII invoice that declares Peppol BIS 3.0 is checked as Peppol automatically", () => {
    const r = validateInvoiceXml(cii(ciiContext()), "auto");
    expect(r.format.id).toBe("peppol-bis-3-cii");
    expect(r.profileApplied).toBe("peppol");
  });
  it("other CII files keep their own rule set under 'auto' (Factur-X sample: no Peppol findings)", () => {
    const r = validateInvoiceXml(getSample("factur-x-en16931")!.content, "auto");
    expect(r.profileApplied).toBe("en16931");
    expect(r.findings.filter((f) => f.source === "Peppol")).toEqual([]);
  });
  it("the 'peppol' profile checks other CII files as Peppol, but leaves Factur-X and XRechnung CII to their own rules", () => {
    expect(validateInvoiceXml(cii(ciiContext("urn:example:own-cius")), "peppol").profileApplied).toBe("peppol");
    for (const id of ["factur-x-en16931", "de-xrechnung-cii-valid"]) {
      const r = validateInvoiceXml(getSample(id)!.content, "peppol");
      expect(r.profileApplied, id).not.toBe("peppol");
      expect(r.findings.filter((f) => f.source === "Peppol"), id).toEqual([]);
    }
  });
  it("R001, R004 and R007 read the CII document context (PEPPOL-EN16931-R001/R004/R007.xml)", () => {
    expect(verdict(cii(ciiContext(PEPPOL_CID, null)), "PEPPOL-EN16931-R001")).toBe("error");
    expect(verdict(cii(ciiContext()), "PEPPOL-EN16931-R001")).toBe("success");
    expect(verdict(cii(ciiContext("urn:cen.eu:en16931:2017#compliant#compliant#urn:www.difi.no:ehf:ver3.0")), "PEPPOL-EN16931-R004")).toBe("error");
    // CII approves only billing 01 and billing with response, not the French processes UBL accepts
    expect(verdict(cii(ciiContext(PEPPOL_CID, "urn:peppol:france:billing:regulated")), "PEPPOL-EN16931-R007")).toBe("error");
    expect(verdict(cii(ciiContext(PEPPOL_CID, "urn:peppol:bis:billing_with_response")), "PEPPOL-EN16931-R007")).toBe("success");
  });
  it("R002 allows one note without a subject code, and has no German exception in CII (PEPPOL-EN16931-R002.xml)", () => {
    const doc = (notes: string) => cii(`${ciiContext()}<rsm:ExchangedDocument>${notes}</rsm:ExchangedDocument>`);
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("success");
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content></ram:IncludedNote><ram:IncludedNote><ram:Content>B</ram:Content></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("error");
    expect(verdict(doc("<ram:IncludedNote><ram:Content>A</ram:Content><ram:SubjectCode>AAI</ram:SubjectCode></ram:IncludedNote>"), "PEPPOL-EN16931-R002")).toBe("error");
  });
  it("R003, R010 and R020 ask for the CII elements (PEPPOL-EN16931-R003/R010/R020.xml)", () => {
    const withAgreement = (a: string) => cii(ciiContext() + ciiTx({ agreement: a }));
    expect(verdict(withAgreement(""), "PEPPOL-EN16931-R003")).toBe("error");
    expect(verdict(withAgreement("<ram:BuyerReference>REF</ram:BuyerReference>"), "PEPPOL-EN16931-R003")).toBe("success");
    expect(verdict(withAgreement("<ram:SellerTradeParty><ram:Name>S</ram:Name></ram:SellerTradeParty>"), "PEPPOL-EN16931-R020")).toBe("error");
    expect(verdict(withAgreement('<ram:BuyerTradeParty><ram:URIUniversalCommunication><ram:URIID schemeID="0208">0403170701</ram:URIID></ram:URIUniversalCommunication></ram:BuyerTradeParty>'), "PEPPOL-EN16931-R010")).toBe("success");
  });
  it("R043 covers document, line and price-level allowances in CII (PEPPOL-EN16931-R043.xml)", () => {
    const ac = (ind: string) => `<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>${ind}</udt:Indicator></ram:ChargeIndicator></ram:SpecifiedTradeAllowanceCharge>`;
    expect(verdict(cii(ciiContext() + ciiTx({ settlement: ac("1") })), "PEPPOL-EN16931-R043")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ settlement: ac("true") })), "PEPPOL-EN16931-R043")).toBe("success");
    const line = `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeAgreement><ram:GrossPriceProductTradePrice><ram:ChargeAmount>10</ram:ChargeAmount><ram:AppliedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>0</udt:Indicator></ram:ChargeIndicator></ram:AppliedTradeAllowanceCharge></ram:GrossPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeSettlement>${ac("false")}</ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`;
    expect(verdict(cii(ciiContext() + ciiTx({ lines: line })), "PEPPOL-EN16931-R043")).toBe("error");
  });
  it("R053 counts the VAT totals in the invoice currency; R055 treats zero as positive in CII", () => {
    const sum = (totals: string, extra = "") =>
      cii(ciiContext() + ciiTx({ settlement: `${extra}<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementHeaderMonetarySummation>${totals}</ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="SEK">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("error");
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("success");
    expect(verdict(sum('<ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount><ram:TaxTotalAmount currencyID="EUR">10</ram:TaxTotalAmount>'), "PEPPOL-EN16931-R053")).toBe("error");
    const signs = (doc: string, acct: string) =>
      `<ram:TaxTotalAmount currencyID="EUR">${doc}</ram:TaxTotalAmount><ram:TaxTotalAmount currencyID="SEK">${acct}</ram:TaxTotalAmount>`;
    const tax = "<ram:TaxCurrencyCode>SEK</ram:TaxCurrencyCode>";
    expect(verdict(sum(signs("0", "-1"), tax), "PEPPOL-EN16931-R055")).toBe("error");
    expect(verdict(sum(signs("-5", "-55"), tax), "PEPPOL-EN16931-R055")).toBe("success");
  });
  it("UBL's R055 accepts a zero VAT total next to a negative one (≤ 0 on both sides)", () => {
    const xml = ubl(`<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode><cac:TaxTotal><cbc:TaxAmount currencyID="EUR">0</cbc:TaxAmount><cac:TaxSubtotal/></cac:TaxTotal><cac:TaxTotal><cbc:TaxAmount currencyID="SEK">-1</cbc:TaxAmount></cac:TaxTotal>`);
    expect(verdict(xml, "PEPPOL-EN16931-R055")).toBe("success");
  });
  it("R061 looks for the mandate in the payment terms (PEPPOL-EN16931-R061.xml)", () => {
    const pm = (terms: string) => cii(ciiContext() + ciiTx({ settlement: `<ram:SpecifiedTradeSettlementPaymentMeans><ram:TypeCode>59</ram:TypeCode></ram:SpecifiedTradeSettlementPaymentMeans>${terms}` }));
    expect(verdict(pm(""), "PEPPOL-EN16931-R061")).toBe("error");
    expect(verdict(pm("<ram:SpecifiedTradePaymentTerms><ram:DirectDebitMandateID>M-1</ram:DirectDebitMandateID></ram:SpecifiedTradePaymentTerms>"), "PEPPOL-EN16931-R061")).toBe("success");
  });
  it("R121 and R130 check the gross price's base quantity as well (PEPPOL-EN16931-R121/R130.xml)", () => {
    const line = (gross: string, billed = '<ram:BilledQuantity unitCode="C62">1</ram:BilledQuantity>') =>
      cii(ciiContext() + ciiTx({ lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeAgreement><ram:GrossPriceProductTradePrice><ram:ChargeAmount>10</ram:ChargeAmount>${gross}</ram:GrossPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeDelivery>${billed}</ram:SpecifiedLineTradeDelivery></ram:IncludedSupplyChainTradeLineItem>` }));
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">0</ram:BasisQuantity>'), "PEPPOL-EN16931-R121")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="KGM">1</ram:BasisQuantity>'), "PEPPOL-EN16931-R130")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">1</ram:BasisQuantity>', "<ram:BilledQuantity>1</ram:BilledQuantity>"), "PEPPOL-EN16931-R130")).toBe("error");
    expect(verdict(line('<ram:BasisQuantity unitCode="C62">1</ram:BasisQuantity>'), "PEPPOL-EN16931-R130")).toBe("success");
  });
  it("R110 and R111 keep line periods inside the invoice period (PEPPOL-EN16931-R110/R111.xml)", () => {
    const d = (v: string) => `<udt:DateTimeString format="102">${v}</udt:DateTimeString>`;
    const xml = cii(ciiContext() + ciiTx({
      lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement><ram:BillingSpecifiedPeriod><ram:StartDateTime>${d("20240101")}</ram:StartDateTime><ram:EndDateTime>${d("20240301")}</ram:EndDateTime></ram:BillingSpecifiedPeriod></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`,
      settlement: `<ram:BillingSpecifiedPeriod><ram:StartDateTime>${d("20240201")}</ram:StartDateTime><ram:EndDateTime>${d("20240228")}</ram:EndDateTime></ram:BillingSpecifiedPeriod>`,
    }));
    expect(verdict(xml, "PEPPOL-EN16931-R110")).toBe("error");
    expect(verdict(xml, "PEPPOL-EN16931-R111")).toBe("error");
  });
  it("CL001 checks every attachment's mime code; CL008 the seller and buyer address scheme, present or not", () => {
    expect(verdict(cii('<ram:AttachmentBinaryObject mimeCode="image/tiff"/>'), "PEPPOL-EN16931-CL001")).toBe("error");
    const seller = (uri: string) => cii(ciiContext() + ciiTx({ agreement: `<ram:SellerTradeParty><ram:URIUniversalCommunication>${uri}</ram:URIUniversalCommunication></ram:SellerTradeParty>` }));
    expect(verdict(seller('<ram:URIID schemeID="0207">1</ram:URIID>'), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(seller("<ram:URIID>a@b.example</ram:URIID>"), "PEPPOL-EN16931-CL008")).toBe("error");
    expect(verdict(seller('<ram:URIID schemeID="0208">0403170701</ram:URIID>'), "PEPPOL-EN16931-CL008")).toBe("success");
  });
  it("P0100 accepts invoice and credit note codes in CII under an approved process (PEPPOL-EN16931-P0100.xml)", () => {
    const doc = (code: string) => cii(`${ciiContext()}<rsm:ExchangedDocument><ram:TypeCode>${code}</ram:TypeCode></rsm:ExchangedDocument>`);
    expect(verdict(doc("381"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(doc("380"), "PEPPOL-EN16931-P0100")).toBe("success");
    expect(verdict(doc("999"), "PEPPOL-EN16931-P0100")).toBe("error");
  });
  it("COMMON-R043 checks every URIID, ID and GlobalID with scheme 0208 (PEPPOL-COMMON-R043.xml)", () => {
    const party = (el: string) => cii(ciiContext() + ciiTx({ agreement: `<ram:BuyerTradeParty>${el}</ram:BuyerTradeParty>` }));
    expect(verdict(party('<ram:GlobalID schemeID="0208">0403170702</ram:GlobalID>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:ID schemeID="0208">BE0403170701</ram:ID>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:URIUniversalCommunication><ram:URIID schemeID="0208">403170701</ram:URIID></ram:URIUniversalCommunication>'), "PEPPOL-COMMON-R043")).toBe("error");
    expect(verdict(party('<ram:GlobalID schemeID="0208">0403170701</ram:GlobalID>'), "PEPPOL-COMMON-R043")).toBe("success");
  });
  it("rules that exist only in Peppol's UBL rules don't run on CII (R008, R044, R046, R051)", () => {
    const xml = cii(ciiContext() + ciiTx({ settlement: '<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:Empty/><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:LineTotalAmount currencyID="NOK">1</ram:LineTotalAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>' }));
    for (const id of ["PEPPOL-EN16931-R008", "PEPPOL-EN16931-R044", "PEPPOL-EN16931-R046", "PEPPOL-EN16931-R051"])
      expect(verdict(xml, id), id).toBe("success");
  });
});

describe("Peppol's Dutch national rules on CII (NL-R-001 … NL-R-009)", () => {
  const seller = (address: string, extra = "") =>
    `<ram:SellerTradeParty>${extra}<ram:PostalTradeAddress>${address}<ram:CountryID>NL</ram:CountryID></ram:PostalTradeAddress></ram:SellerTradeParty>`;
  const full = "<ram:PostcodeCode>1234AB</ram:PostcodeCode><ram:LineOne>Straat 1</ram:LineOne><ram:CityName>Groningen</ram:CityName>";
  it("NL-R-002 asks for street, city and post code in a Dutch seller's address", () => {
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller("<ram:LineOne>Straat 1</ram:LineOne>") })), "NL-R-002")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full) })), "NL-R-002")).toBe("success");
  });
  it("NL-R-001 needs the invoice reference on a CII credit note (type 381)", () => {
    const doc = (refs: string) =>
      cii(`${ciiContext()}<rsm:ExchangedDocument><ram:TypeCode>381</ram:TypeCode></rsm:ExchangedDocument>${ciiTx({ agreement: seller(full), settlement: refs })}`);
    expect(verdict(doc(""), "NL-R-001")).toBe("error");
    expect(verdict(doc("<ram:InvoiceReferencedDocument><ram:IssuerAssignedID>F-1</ram:IssuerAssignedID></ram:InvoiceReferencedDocument>"), "NL-R-001")).toBe("success");
  });
  it("NL-R-003 asks for a KvK or OIN legal ID; NL-R-007 for payment instructions when money is due", () => {
    const legal = (scheme: string) => `<ram:SpecifiedLegalOrganization><ram:ID schemeID="${scheme}">12345678</ram:ID></ram:SpecifiedLegalOrganization>`;
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full, legal("0208")) })), "NL-R-003")).toBe("error");
    expect(verdict(cii(ciiContext() + ciiTx({ agreement: seller(full, legal("0106")) })), "NL-R-003")).toBe("success");
    const due = (amount: string) => cii(ciiContext() + ciiTx({ agreement: seller(full), settlement: `<ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:DuePayableAmount>${amount}</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(due("100.00"), "NL-R-007")).toBe("error");
    expect(verdict(due("0.00"), "NL-R-007")).toBe("success");
  });
});

describe("EN 16931 rules the official artefacts check differently from the standard's text", () => {
  const payable = (root: "Invoice" | "CreditNote") =>
    ubl('<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode><cac:LegalMonetaryTotal><cbc:PayableAmount currencyID="EUR">100.00</cbc:PayableAmount></cac:LegalMonetaryTotal>', root);
  it("BR-CO-25 is only a warning on invoices: CEN dropped it from the official rules in 1.3.16", () => {
    expect(verdict(payable("Invoice"), "BR-CO-25", "en16931")).toBe("warning");
    expect(verdict(payable("Invoice"), "BR-CO-25", "peppol")).toBe("warning");
  });
  it("BR-CO-25 never fires on credit notes (CreditNote-unit-UBL/BR-CO-25.xml)", () => {
    expect(verdict(payable("CreditNote"), "BR-CO-25", "en16931")).toBe("success");
  });
  it("BR-CO-25 stays an error for Factur-X, whose rule packs still check it", () => {
    const xml = getSample("factur-x-en16931")!.content
      .replace(/<ram:SpecifiedTradePaymentTerms>[\s\S]*?<\/ram:SpecifiedTradePaymentTerms>/, "");
    expect(xml).not.toContain("SpecifiedTradePaymentTerms");
    expect(verdict(xml, "BR-CO-25", "auto")).toBe("error");
  });
  it("BR-AE-10 accepts any exemption reason code or text (Invoice-unit-UBL/BR-AE-10.xml)", () => {
    const xml = getSample("reverse-charge-valid")!.content.replace(
      "<cbc:TaxExemptionReasonCode>VATEX-EU-AE</cbc:TaxExemptionReasonCode>",
      "<cbc:TaxExemptionReasonCode>10</cbc:TaxExemptionReasonCode>",
    );
    expect(xml).toContain("<cbc:TaxExemptionReasonCode>10</cbc:TaxExemptionReasonCode>");
    expect(verdict(xml, "BR-AE-10", "en16931")).toBe("success");
  });
  it("BR-CO-15 in CII also accepts a grand total equal to the tax basis without a VAT total", () => {
    const totals = (grand: string) =>
      cii(ciiTx({ settlement: `<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:TaxBasisTotalAmount>100.00</ram:TaxBasisTotalAmount><ram:GrandTotalAmount>${grand}</ram:GrandTotalAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(totals("100.00"), "BR-CO-15", "en16931")).toBe("success");
    expect(verdict(totals("121.00"), "BR-CO-15", "en16931")).toBe("error");
  });
  it("BR-VAT-01 (BR-Z-01, BR-E-01 …): exactly one breakdown row per category; in CII a row also needs a line using it", () => {
    const tax = (cat: string) => `<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>${cat}</ram:CategoryCode><ram:RateApplicablePercent>0</ram:RateApplicablePercent></ram:ApplicableTradeTax>`;
    const line = (cat: string) => `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement>${tax(cat)}</ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>`;
    const xml = (lines: string, rows: string) => cii(ciiTx({ lines, settlement: rows }));
    expect(verdict(xml(line("Z"), tax("Z")), "BR-VAT-01", "en16931")).toBe("success");
    expect(verdict(xml(line("Z"), tax("Z") + tax("Z")), "BR-VAT-01", "en16931")).toBe("error");
    expect(verdict(xml("", tax("E")), "BR-VAT-01", "en16931")).toBe("error");
    // In UBL a breakdown row on its own counts as using the category (Invoice-unit-UBL/BR-E-01.xml)
    const row = '<cac:TaxTotal><cac:TaxSubtotal><cac:TaxCategory><cbc:ID>E</cbc:ID><cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme></cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal>';
    expect(verdict(ubl(row), "BR-VAT-01", "en16931")).toBe("success");
  });
  it("BR-IC-11 in CII needs a delivery date or a start or end date in the invoice period", () => {
    const k = '<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>K</ram:CategoryCode><ram:RateApplicablePercent>0</ram:RateApplicablePercent></ram:ApplicableTradeTax>';
    const xml = (period: string) => cii(ciiTx({ settlement: k + period }));
    expect(verdict(xml("<ram:BillingSpecifiedPeriod><ram:Description>x</ram:Description></ram:BillingSpecifiedPeriod>"), "BR-IC-11", "en16931")).toBe("error");
    expect(verdict(xml('<ram:BillingSpecifiedPeriod><ram:StartDateTime><udt:DateTimeString format="102">20240101</udt:DateTimeString></ram:StartDateTime></ram:BillingSpecifiedPeriod>'), "BR-IC-11", "en16931")).toBe("success");
  });
});

describe("Peppol BIS 3.0 rules added in Peppol UBL check 1.4.0", () => {
  const ac = (charge: boolean, codes: string[]) =>
    `<cac:AllowanceCharge><cbc:ChargeIndicator>${charge}</cbc:ChargeIndicator>${codes.map((c) => `<cbc:AllowanceChargeReasonCode>${c}</cbc:AllowanceChargeReasonCode>`).join("")}</cac:AllowanceCharge>`;
  const ciiAc = (charge: boolean, code: string) =>
    `<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>${charge}</udt:Indicator></ram:ChargeIndicator><ram:ReasonCode>${code}</ram:ReasonCode></ram:SpecifiedTradeAllowanceCharge>`;

  it("CL002 and CL003 check allowance and charge reason codes against Peppol's lists (PEPPOL-EN16931-CL002/CL003.xml)", () => {
    expect(verdict(ubl(ac(false, ["60", "70", "100"])), "PEPPOL-EN16931-CL002")).toBe("success");
    expect(verdict(ubl(ac(false, ["40", "80", "110"])), "PEPPOL-EN16931-CL002")).toBe("error");
    expect(verdict(ubl(ac(true, ["AA", "ABL", "ZZZ"])), "PEPPOL-EN16931-CL003")).toBe("success");
    expect(verdict(ubl(ac(true, ["XYZ"])), "PEPPOL-EN16931-CL003")).toBe("error");
    // An allowance code on a charge is a charge-code question, so CL002 leaves it alone
    expect(verdict(ubl(ac(true, ["95"])), "PEPPOL-EN16931-CL002")).toBe("success");
    const settle = (s: string) => cii(ciiTx({ settlement: s }));
    expect(verdict(settle(ciiAc(false, "95")), "PEPPOL-EN16931-CL002")).toBe("success");
    expect(verdict(settle(ciiAc(false, "110")), "PEPPOL-EN16931-CL002")).toBe("error");
    expect(verdict(settle(ciiAc(true, "FC")), "PEPPOL-EN16931-CL003")).toBe("success");
    expect(verdict(settle(ciiAc(true, "XYZ")), "PEPPOL-EN16931-CL003")).toBe("error");
  });

  it("CL007 needs an ISO 4217 currencyID on every UBL amount, and on CII VAT totals that carry one (PEPPOL-EN16931-CL007.xml)", () => {
    const total = (attr: string) => ubl(`<cac:LegalMonetaryTotal><cbc:PayableAmount${attr}>100.00</cbc:PayableAmount></cac:LegalMonetaryTotal>`);
    expect(verdict(total(' currencyID="EUR"'), "PEPPOL-EN16931-CL007")).toBe("success");
    expect(verdict(total(' currencyID="EURO"'), "PEPPOL-EN16931-CL007")).toBe("error");
    expect(verdict(total(""), "PEPPOL-EN16931-CL007")).toBe("error");
    const ciiTotal = (attr: string) =>
      cii(ciiTx({ settlement: `<ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:TaxTotalAmount${attr}>21.00</ram:TaxTotalAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>` }));
    expect(verdict(ciiTotal(' currencyID="NOK"'), "PEPPOL-EN16931-CL007")).toBe("success");
    expect(verdict(ciiTotal(' currencyID="NOKK"'), "PEPPOL-EN16931-CL007")).toBe("error");
    expect(verdict(ciiTotal(""), "PEPPOL-EN16931-CL007")).toBe("success");
  });

  it("F001 wants real YYYY-MM-DD dates in UBL and format 102 dates from 2000 on in CII (PEPPOL-EN16931-F001.xml)", () => {
    expect(verdict(ubl("<cbc:IssueDate>2024-02-29</cbc:IssueDate>"), "PEPPOL-EN16931-F001")).toBe("success");
    expect(verdict(ubl("<cbc:IssueDate>2023-02-29</cbc:IssueDate>"), "PEPPOL-EN16931-F001")).toBe("error");
    expect(verdict(ubl("<cbc:DueDate>2024-1-05</cbc:DueDate>"), "PEPPOL-EN16931-F001")).toBe("error");
    const date = (format: string, value: string) =>
      cii(`<rsm:ExchangedDocument><ram:IssueDateTime><udt:DateTimeString format="${format}">${value}</udt:DateTimeString></ram:IssueDateTime></rsm:ExchangedDocument>`);
    expect(verdict(date("102", "20240131"), "PEPPOL-EN16931-F001")).toBe("success");
    expect(verdict(date("102", "2024-01-31"), "PEPPOL-EN16931-F001")).toBe("error");
    expect(verdict(date("203", "202401311200"), "PEPPOL-EN16931-F001")).toBe("error");
    expect(verdict(date("102", "19991231"), "PEPPOL-EN16931-F001")).toBe("error");
  });

  it("P0104 … P0111 tie each VATEX-EU code to its VAT category, wherever the category sits (PEPPOL-EN16931-P0104 … P0111.xml)", () => {
    const pairs: [string, string, string][] = [
      ["P0104", "VATEX-EU-G", "G"], ["P0105", "VATEX-EU-O", "O"], ["P0106", "VATEX-EU-IC", "K"], ["P0107", "VATEX-EU-AE", "AE"],
      ["P0108", "VATEX-EU-D", "E"], ["P0109", "VATEX-EU-F", "E"], ["P0110", "VATEX-EU-I", "E"], ["P0111", "VATEX-EU-J", "E"],
    ];
    const subtotal = (cat: string, code: string) =>
      ubl(`<cac:TaxTotal><cac:TaxSubtotal><cac:TaxCategory><cbc:ID>${cat}</cbc:ID><cbc:TaxExemptionReasonCode>${code}</cbc:TaxExemptionReasonCode><cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme></cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal>`);
    for (const [rule, code, cat] of pairs) {
      expect(verdict(subtotal(cat, code), `PEPPOL-EN16931-${rule}`), `${rule} ${cat}`).toBe("success");
      expect(verdict(subtotal(cat === "E" ? "S" : "E", code), `PEPPOL-EN16931-${rule}`), `${rule} wrong category`).toBe("error");
      // The code is compared case-insensitively
      expect(verdict(subtotal("Z", code.toLowerCase()), `PEPPOL-EN16931-${rule}`), `${rule} lower case`).toBe("error");
    }
    const allowance = ubl(`<cac:AllowanceCharge><cbc:ChargeIndicator>false</cbc:ChargeIndicator><cac:TaxCategory><cbc:ID>S</cbc:ID><cbc:TaxExemptionReasonCode>VATEX-EU-G</cbc:TaxExemptionReasonCode><cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme></cac:TaxCategory></cac:AllowanceCharge>`);
    expect(verdict(allowance, "PEPPOL-EN16931-P0104")).toBe("error");
    // They are UBL rules: Peppol's CII rules have no counterpart
    const ciiRow = cii(ciiTx({ settlement: "<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:ExemptionReasonCode>VATEX-EU-G</ram:ExemptionReasonCode><ram:CategoryCode>S</ram:CategoryCode></ram:ApplicableTradeTax>" }));
    expect(verdict(ciiRow, "PEPPOL-EN16931-P0104")).toBe("success");
  });

  it("R006 allows one invoiced object (type 130) on document level, in CII only (PEPPOL-EN16931-R006.xml)", () => {
    const refs = (n: number, type = "130") =>
      Array.from({ length: n }, (_, i) => `<ram:AdditionalReferencedDocument><ram:IssuerAssignedID>OBJ-${i}</ram:IssuerAssignedID><ram:TypeCode>${type}</ram:TypeCode></ram:AdditionalReferencedDocument>`).join("");
    expect(verdict(cii(ciiTx({ agreement: refs(1) })), "PEPPOL-EN16931-R006")).toBe("success");
    expect(verdict(cii(ciiTx({ agreement: refs(2, "916") })), "PEPPOL-EN16931-R006")).toBe("success");
    expect(verdict(cii(ciiTx({ agreement: refs(2) })), "PEPPOL-EN16931-R006")).toBe("error");
    const ublRefs = '<cac:AdditionalDocumentReference><cbc:ID>A</cbc:ID><cbc:DocumentTypeCode>130</cbc:DocumentTypeCode></cac:AdditionalDocumentReference><cac:AdditionalDocumentReference><cbc:ID>B</cbc:ID><cbc:DocumentTypeCode>130</cbc:DocumentTypeCode></cac:AdditionalDocumentReference>';
    expect(verdict(ubl(ublRefs), "PEPPOL-EN16931-R006")).toBe("success");
  });

  it("R054 asks for exactly one VAT total in the accounting currency when TaxCurrencyCode is given, and none otherwise (PEPPOL-EN16931-R054.xml)", () => {
    const sub = '<cac:TaxTotal><cbc:TaxAmount currencyID="EUR">25.00</cbc:TaxAmount><cac:TaxSubtotal><cbc:TaxAmount currencyID="EUR">25.00</cbc:TaxAmount></cac:TaxSubtotal></cac:TaxTotal>';
    const acc = '<cac:TaxTotal><cbc:TaxAmount currencyID="SEK">280.00</cbc:TaxAmount></cac:TaxTotal>';
    const cur = "<cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode>";
    expect(verdict(ubl(sub), "PEPPOL-EN16931-R054")).toBe("success");
    expect(verdict(ubl(cur + sub + acc), "PEPPOL-EN16931-R054")).toBe("success");
    expect(verdict(ubl(cur + sub), "PEPPOL-EN16931-R054")).toBe("error");
    expect(verdict(ubl(sub + acc), "PEPPOL-EN16931-R054")).toBe("error");
    expect(verdict(ubl(cur + sub + acc + acc), "PEPPOL-EN16931-R054")).toBe("error");
    const ciiSettle = (taxCur: string, totals: string[]) =>
      cii(`<rsm:SupplyChainTradeTransaction><ram:ApplicableHeaderTradeSettlement>${taxCur}<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode><ram:SpecifiedTradeSettlementHeaderMonetarySummation>${totals.map((c) => `<ram:TaxTotalAmount currencyID="${c}">10.00</ram:TaxTotalAmount>`).join("")}</ram:SpecifiedTradeSettlementHeaderMonetarySummation></ram:ApplicableHeaderTradeSettlement></rsm:SupplyChainTradeTransaction>`);
    const ciiCur = "<ram:TaxCurrencyCode>SEK</ram:TaxCurrencyCode>";
    expect(verdict(ciiSettle("", ["EUR"]), "PEPPOL-EN16931-R054")).toBe("success");
    expect(verdict(ciiSettle(ciiCur, ["EUR", "SEK"]), "PEPPOL-EN16931-R054")).toBe("success");
    expect(verdict(ciiSettle(ciiCur, ["EUR"]), "PEPPOL-EN16931-R054")).toBe("error");
    expect(verdict(ciiSettle("", ["EUR", "SEK"]), "PEPPOL-EN16931-R054")).toBe("error");
  });

  it("R080 allows one project reference (type 50): on UBL credit notes, and in CII (PEPPOL-EN16931-R080.xml)", () => {
    const two = '<cac:AdditionalDocumentReference><cbc:ID>P1</cbc:ID><cbc:DocumentTypeCode>50</cbc:DocumentTypeCode></cac:AdditionalDocumentReference><cac:AdditionalDocumentReference><cbc:ID>P2</cbc:ID><cbc:DocumentTypeCode>50</cbc:DocumentTypeCode></cac:AdditionalDocumentReference>';
    expect(verdict(ubl(two, "CreditNote"), "PEPPOL-EN16931-R080")).toBe("error");
    expect(verdict(ubl(two.replace("<cbc:DocumentTypeCode>50</cbc:DocumentTypeCode>", "<cbc:DocumentTypeCode>130</cbc:DocumentTypeCode>"), "CreditNote"), "PEPPOL-EN16931-R080")).toBe("success");
    // An invoice states its project in ProjectReference; Peppol's rules leave these references alone
    expect(verdict(ubl(two), "PEPPOL-EN16931-R080")).toBe("success");
    const refs = (n: number) =>
      Array.from({ length: n }, (_, i) => `<ram:AdditionalReferencedDocument><ram:IssuerAssignedID>P${i}</ram:IssuerAssignedID><ram:TypeCode>50</ram:TypeCode></ram:AdditionalReferencedDocument>`).join("");
    expect(verdict(cii(ciiTx({ agreement: refs(1) })), "PEPPOL-EN16931-R080")).toBe("success");
    expect(verdict(cii(ciiTx({ agreement: refs(2) })), "PEPPOL-EN16931-R080")).toBe("error");
  });

  it("R100 and R101: a line may carry one document reference, and only for its invoiced object (PEPPOL-EN16931-R100/R101.xml)", () => {
    const docRef = (type: string) => `<cac:DocumentReference><cbc:ID>OBJ</cbc:ID><cbc:DocumentTypeCode>${type}</cbc:DocumentTypeCode></cac:DocumentReference>`;
    const line = (refs: string, root: "Invoice" | "CreditNote" = "Invoice") =>
      ubl(`<cac:${root}Line><cbc:ID>1</cbc:ID>${refs}</cac:${root}Line>`, root);
    expect(verdict(line(docRef("130")), "PEPPOL-EN16931-R100")).toBe("success");
    expect(verdict(line(docRef("130") + docRef("130")), "PEPPOL-EN16931-R100")).toBe("error");
    expect(verdict(line(docRef("130") + docRef("130"), "CreditNote"), "PEPPOL-EN16931-R100")).toBe("error");
    expect(verdict(line(docRef("130")), "PEPPOL-EN16931-R101")).toBe("success");
    expect(verdict(line(docRef("916")), "PEPPOL-EN16931-R101")).toBe("error");
    // UBL: one reference of type 130 among several is enough for R101
    expect(verdict(line(docRef("916") + docRef("130")), "PEPPOL-EN16931-R101")).toBe("success");
    const ciiLine = (types: string[]) =>
      cii(ciiTx({ lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement>${types.map((t) => `<ram:AdditionalReferencedDocument><ram:IssuerAssignedID>OBJ</ram:IssuerAssignedID><ram:TypeCode>${t}</ram:TypeCode></ram:AdditionalReferencedDocument>`).join("")}</ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>` }));
    expect(verdict(ciiLine(["130"]), "PEPPOL-EN16931-R100")).toBe("success");
    expect(verdict(ciiLine(["130", "130"]), "PEPPOL-EN16931-R100")).toBe("error");
    // CII's R100 counts invoiced objects only
    expect(verdict(ciiLine(["130", "916"]), "PEPPOL-EN16931-R100")).toBe("success");
    expect(verdict(ciiLine(["916"]), "PEPPOL-EN16931-R101")).toBe("error");
  });
});

describe("EN 16931 rules added in Peppol UBL check 1.4.0: how CII differs from UBL", () => {
  const row = (cat: string, extra = "") =>
    `<ram:ApplicableTradeTax><ram:CalculatedAmount>0.00</ram:CalculatedAmount><ram:TypeCode>VAT</ram:TypeCode>${extra}<ram:BasisAmount>100.00</ram:BasisAmount><ram:CategoryCode>${cat}</ram:CategoryCode><ram:RateApplicablePercent>0</ram:RateApplicablePercent></ram:ApplicableTradeTax>`;
  const settle = (s: string) => cii(ciiTx({ settlement: `<ram:InvoiceCurrencyCode>EUR</ram:InvoiceCurrencyCode>${s}` }));

  it("CII checks intra-community supply (K) under BR-IC and the IGIC/IPSI categories (L, M) under swapped IDs, as the official CII rules do", () => {
    // CEN's CII rules check category L under the BR-IP IDs and M under BR-IG (the UBL rules do the reverse)
    expect(verdict(settle(row("L", "<ram:ExemptionReason>x</ram:ExemptionReason>")), "BR-IP-10", "en16931")).toBe("error");
    expect(verdict(settle(row("L", "<ram:ExemptionReason>x</ram:ExemptionReason>")), "BR-IG-10", "en16931")).toBe("success");
    expect(verdict(settle(row("M", "<ram:ExemptionReason>x</ram:ExemptionReason>")), "BR-IG-10", "en16931")).toBe("error");
    // BR-IG-09 and BR-IP-09 can't fail in CII: the official test there is always true
    expect(verdict(settle(row("M").replace("<ram:CalculatedAmount>0.00", "<ram:CalculatedAmount>99.00")), "BR-IG-09", "en16931")).toBe("success");
  });

  it("BR-CO-21 … BR-CO-24 count an empty reason element as given (Invoice-unit-UBL/BR-CO-21 … 24.xml)", () => {
    const allowance = (reason: string) =>
      settle(`<ram:SpecifiedTradeAllowanceCharge><ram:ChargeIndicator><udt:Indicator>false</udt:Indicator></ram:ChargeIndicator><ram:ActualAmount>10.00</ram:ActualAmount>${reason}</ram:SpecifiedTradeAllowanceCharge>`);
    expect(verdict(allowance("<ram:Reason/>"), "BR-CO-21", "en16931")).toBe("success");
    expect(verdict(allowance(""), "BR-CO-21", "en16931")).toBe("error");
    expect(verdict(ubl('<cac:AllowanceCharge><cbc:ChargeIndicator>true</cbc:ChargeIndicator><cbc:AllowanceChargeReason/></cac:AllowanceCharge>'), "BR-CO-22", "en16931")).toBe("success");
    expect(verdict(ubl('<cac:AllowanceCharge><cbc:ChargeIndicator>true</cbc:ChargeIndicator></cac:AllowanceCharge>'), "BR-CO-22", "en16931")).toBe("error");
  });

  it("BR-51 is a warning in UBL but an error in CII (Invoice-unit-UBL/BR-51.xml)", () => {
    const card = (n: string) => ubl(`<cac:PaymentMeans><cac:CardAccount><cbc:PrimaryAccountNumberID>${n}</cbc:PrimaryAccountNumberID></cac:CardAccount></cac:PaymentMeans>`);
    expect(verdict(card("123456"), "BR-51", "en16931")).toBe("success");
    expect(verdict(card("12345678901234"), "BR-51", "en16931")).toBe("warning");
    const ciiCard = (n: string) => settle(`<ram:SpecifiedTradeSettlementPaymentMeans><ram:TypeCode>48</ram:TypeCode><ram:ApplicableTradeSettlementFinancialCard><ram:ID>${n}</ram:ID></ram:ApplicableTradeSettlementFinancialCard></ram:SpecifiedTradeSettlementPaymentMeans>`);
    expect(verdict(ciiCard("1234569876"), "BR-51", "en16931")).toBe("success");
    expect(verdict(ciiCard("12345678901234"), "BR-51", "en16931")).toBe("error");
  });

  it("BR-CL-05 checks the tax currency in both syntaxes; the UBL data-type rules don't run on CII", () => {
    expect(verdict(ubl("<cbc:TaxCurrencyCode>ABC</cbc:TaxCurrencyCode>"), "BR-CL-05", "en16931")).toBe("error");
    expect(verdict(ubl("<cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode>"), "BR-CL-05", "en16931")).toBe("success");
    expect(verdict(settle("<ram:TaxCurrencyCode>ABC</ram:TaxCurrencyCode>"), "BR-CL-05", "en16931")).toBe("error");
    expect(verdict(ubl('<cac:LegalMonetaryTotal><cbc:PayableAmount currencyID="EUR">1.005</cbc:PayableAmount></cac:LegalMonetaryTotal>'), "UBL-DT-01", "en16931")).toBe("error");
    expect(verdict(settle("<ram:SpecifiedTradeSettlementHeaderMonetarySummation><ram:DuePayableAmount>1.005</ram:DuePayableAmount></ram:SpecifiedTradeSettlementHeaderMonetarySummation>"), "UBL-DT-01", "en16931")).toBe("success");
  });
});

describe("Official rules without official unit tests, checked as the Schematron is written (1.4.0)", () => {
  const vat = "<cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme>";
  const sellerTax = `<cac:AccountingSupplierParty><cac:Party><cac:PartyTaxScheme><cbc:CompanyID>BE0123456749</cbc:CompanyID>${vat}</cac:PartyTaxScheme></cac:Party></cac:AccountingSupplierParty>`;
  const buyerTax = `<cac:AccountingCustomerParty><cac:Party><cac:PartyTaxScheme><cbc:CompanyID>NL123456789B01</cbc:CompanyID>${vat}</cac:PartyTaxScheme></cac:Party></cac:AccountingCustomerParty>`;
  const buyerLegal = "<cac:AccountingCustomerParty><cac:Party><cac:PartyLegalEntity><cbc:CompanyID>0123456789</cbc:CompanyID></cac:PartyLegalEntity></cac:Party></cac:AccountingCustomerParty>";
  const docAc = (charge: boolean, cat: string) =>
    `<cac:AllowanceCharge><cbc:ChargeIndicator>${charge}</cbc:ChargeIndicator><cac:TaxCategory><cbc:ID>${cat}</cbc:ID>${vat}</cac:TaxCategory></cac:AllowanceCharge>`;

  it("BR-E-03/04 and BR-IG-03/04 need a seller VAT identifier next to an exempt or IGIC allowance or charge", () => {
    expect(verdict(ubl(docAc(false, "E")), "BR-E-03", "en16931")).toBe("error");
    expect(verdict(ubl(sellerTax + docAc(false, "E")), "BR-E-03", "en16931")).toBe("success");
    expect(verdict(ubl(docAc(true, "E")), "BR-E-04", "en16931")).toBe("error");
    expect(verdict(ubl(docAc(false, "L")), "BR-IG-03", "en16931")).toBe("error");
    expect(verdict(ubl(docAc(true, "L")), "BR-IG-04", "en16931")).toBe("error");
    // UBL's BR-IG-04 reads the category as written in its second half, so " L " slips through
    expect(verdict(ubl(docAc(true, " L ")), "BR-IG-04", "en16931")).toBe("success");
    expect(verdict(ubl(docAc(false, " L ")), "BR-IG-03", "en16931")).toBe("error");
  });

  it("BR-AE-03/04 need the seller's and the buyer's identifier (VAT number or legal registration)", () => {
    expect(verdict(ubl(sellerTax + docAc(false, "AE")), "BR-AE-03", "en16931")).toBe("error");
    expect(verdict(ubl(sellerTax + buyerTax + docAc(false, "AE")), "BR-AE-03", "en16931")).toBe("success");
    expect(verdict(ubl(sellerTax + buyerLegal + docAc(true, "AE")), "BR-AE-04", "en16931")).toBe("success");
    expect(verdict(ubl(buyerTax + docAc(true, "AE")), "BR-AE-04", "en16931")).toBe("error");
  });

  it("BR-IG-02 / BR-IP-02: IGIC and IPSI lines need a seller VAT identifier; CII swaps the categories", () => {
    const line = (cat: string) => `<cac:InvoiceLine><cbc:ID>1</cbc:ID><cac:Item><cac:ClassifiedTaxCategory><cbc:ID>${cat}</cbc:ID>${vat}</cac:ClassifiedTaxCategory></cac:Item></cac:InvoiceLine>`;
    expect(verdict(ubl(line("L")), "BR-IG-02", "en16931")).toBe("error");
    expect(verdict(ubl(sellerTax + line("L")), "BR-IG-02", "en16931")).toBe("success");
    expect(verdict(ubl(line("M")), "BR-IP-02", "en16931")).toBe("error");
    const ciiLine = (cat: string) =>
      cii(ciiTx({ lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedLineTradeSettlement><ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>${cat}</ram:CategoryCode></ram:ApplicableTradeTax></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem>` }));
    expect(verdict(ciiLine("M"), "BR-IG-02", "en16931")).toBe("error");
    expect(verdict(ciiLine("L"), "BR-IG-02", "en16931")).toBe("success");
    expect(verdict(ciiLine("L"), "BR-IP-02", "en16931")).toBe("error");
  });

  it("BR-50 asks for the account identifier of a credit transfer (codes 30 and 58)", () => {
    const pm = (code: string, account: string) => ubl(`<cac:PaymentMeans><cbc:PaymentMeansCode>${code}</cbc:PaymentMeansCode><cac:PayeeFinancialAccount>${account}</cac:PayeeFinancialAccount></cac:PaymentMeans>`);
    expect(verdict(pm("30", "<cbc:ID>BE68539007547034</cbc:ID>"), "BR-50", "en16931")).toBe("success");
    expect(verdict(pm("58", "<cbc:ID> </cbc:ID>"), "BR-50", "en16931")).toBe("error");
    expect(verdict(pm("31", ""), "BR-50", "en16931")).toBe("success");
    const ciiPm = (account: string) =>
      cii(ciiTx({ settlement: `<ram:SpecifiedTradeSettlementPaymentMeans><ram:TypeCode>58</ram:TypeCode><ram:PayeePartyCreditorFinancialAccount>${account}</ram:PayeePartyCreditorFinancialAccount></ram:SpecifiedTradeSettlementPaymentMeans>` }));
    expect(verdict(ciiPm("<ram:ProprietaryID>12345</ram:ProprietaryID>"), "BR-50", "en16931")).toBe("success");
    expect(verdict(ciiPm("<ram:IBANID/>"), "BR-50", "en16931")).toBe("error");
  });

  it("BR-B-01 / BR-B-02: split payment (B) only on Italian invoices, and never with standard rate", () => {
    const country = (c: string) => `<cac:AccountingSupplierParty><cac:Party><cac:PostalAddress><cac:Country><cbc:IdentificationCode>${c}</cbc:IdentificationCode></cac:Country></cac:PostalAddress></cac:Party></cac:AccountingSupplierParty>`;
    const row = (cat: string) => `<cac:TaxTotal><cac:TaxSubtotal><cac:TaxCategory><cbc:ID>${cat}</cbc:ID>${vat}</cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal>`;
    expect(verdict(ubl(country("IT") + row("B")), "BR-B-01", "en16931")).toBe("success");
    expect(verdict(ubl(country("BE") + row("B")), "BR-B-01", "en16931")).toBe("error");
    expect(verdict(ubl(country("BE") + row("S")), "BR-B-01", "en16931")).toBe("success");
    expect(verdict(ubl(row("B") + row("S")), "BR-B-02", "en16931")).toBe("error");
    expect(verdict(ubl(row("B")), "BR-B-02", "en16931")).toBe("success");
    const ciiRows = (cats: string[], countryId: string) =>
      cii(ciiTx({ agreement: `<ram:SellerTradeParty><ram:PostalTradeAddress><ram:CountryID>${countryId}</ram:CountryID></ram:PostalTradeAddress></ram:SellerTradeParty>`, settlement: cats.map((c) => `<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>${c}</ram:CategoryCode></ram:ApplicableTradeTax>`).join("") }));
    expect(verdict(ciiRows(["B"], "FR"), "BR-B-01", "en16931")).toBe("error");
    expect(verdict(ciiRows(["B", "S"], "IT"), "BR-B-02", "en16931")).toBe("error");
  });

  it("BR-CL-06 and Peppol's CL006 check the VAT point date code (UBL 3, 35, 432; CII 5, 29, 72)", () => {
    const period = (code: string) => ubl(`<cac:InvoicePeriod><cbc:DescriptionCode>${code}</cbc:DescriptionCode></cac:InvoicePeriod>`);
    expect(verdict(period("35"), "BR-CL-06", "en16931")).toBe("success");
    expect(verdict(period("5"), "BR-CL-06", "en16931")).toBe("error");
    expect(verdict(period("5"), "PEPPOL-EN16931-CL006")).toBe("error");
    expect(verdict(period(" 432 "), "PEPPOL-EN16931-CL006")).toBe("success");
    const due = (code: string) => cii(ciiTx({ settlement: `<ram:ApplicableTradeTax><ram:DueDateTypeCode>${code}</ram:DueDateTypeCode></ram:ApplicableTradeTax>` }));
    expect(verdict(due("29"), "BR-CL-06", "en16931")).toBe("success");
    expect(verdict(due("35"), "BR-CL-06", "en16931")).toBe("error");
  });

  it("BR-CL-08 checks a note's subject code: UBL the three letters between the first two #, CII ram:SubjectCode", () => {
    const note = (text: string) => ubl(`<cbc:Note>${text}</cbc:Note>`);
    expect(verdict(note("#AAI#Payment within 30 days"), "BR-CL-08", "en16931")).toBe("success");
    expect(verdict(note("#XYZ#Payment within 30 days"), "BR-CL-08", "en16931")).toBe("error");
    // Not a three-character code between two #, so not tested; "AA " is part of the written-out list
    expect(verdict(note("#AB#x"), "BR-CL-08", "en16931")).toBe("success");
    expect(verdict(note("#AA #x"), "BR-CL-08", "en16931")).toBe("success");
    const subject = (code: string) => cii(`<rsm:ExchangedDocument><ram:IncludedNote><ram:Content>x</ram:Content><ram:SubjectCode>${code}</ram:SubjectCode></ram:IncludedNote></rsm:ExchangedDocument>`);
    expect(verdict(subject("SUR"), "BR-CL-08", "en16931")).toBe("success");
    expect(verdict(subject("XYZ"), "BR-CL-08", "en16931")).toBe("error");
  });

  it("BR-CL-10, -21 and -26 want ISO 6523 schemes for party, item and delivery location identifiers", () => {
    const party = (holder: string, scheme: string) => ubl(`<cac:${holder}><cac:Party><cac:PartyIdentification><cbc:ID schemeID="${scheme}">123</cbc:ID></cac:PartyIdentification></cac:Party></cac:${holder}>`);
    expect(verdict(party("AccountingCustomerParty", "0088"), "BR-CL-10", "en16931")).toBe("success");
    expect(verdict(party("AccountingCustomerParty", "9999"), "BR-CL-10", "en16931")).toBe("error");
    // A SEPA creditor identifier is fine for the seller (and payee), not for the buyer
    expect(verdict(party("AccountingSupplierParty", "SEPA"), "BR-CL-10", "en16931")).toBe("success");
    expect(verdict(party("AccountingCustomerParty", "SEPA"), "BR-CL-10", "en16931")).toBe("error");
    expect(verdict(ubl('<cac:InvoiceLine><cac:Item><cac:StandardItemIdentification><cbc:ID schemeID="0160">5412345000013</cbc:ID></cac:StandardItemIdentification></cac:Item></cac:InvoiceLine>'), "BR-CL-21", "en16931")).toBe("success");
    expect(verdict(ubl('<cac:InvoiceLine><cac:Item><cac:StandardItemIdentification><cbc:ID schemeID="EAN">5412345000013</cbc:ID></cac:StandardItemIdentification></cac:Item></cac:InvoiceLine>'), "BR-CL-21", "en16931")).toBe("error");
    expect(verdict(ubl('<cac:Delivery><cac:DeliveryLocation><cbc:ID schemeID="GLN">5412345000013</cbc:ID></cac:DeliveryLocation></cac:Delivery>'), "BR-CL-26", "en16931")).toBe("error");
    // CII: a GlobalID under the product or the ship-to party is BR-CL-21's or BR-CL-26's, not BR-CL-10's
    const ciiProduct = (scheme: string) => cii(ciiTx({ lines: `<ram:IncludedSupplyChainTradeLineItem><ram:SpecifiedTradeProduct><ram:GlobalID schemeID="${scheme}">1</ram:GlobalID></ram:SpecifiedTradeProduct></ram:IncludedSupplyChainTradeLineItem>` }));
    expect(verdict(ciiProduct("EAN"), "BR-CL-21", "en16931")).toBe("error");
    expect(verdict(ciiProduct("EAN"), "BR-CL-10", "en16931")).toBe("success");
    const shipTo = (scheme: string) => cii(ciiTx({ delivery: `<ram:ShipToTradeParty><ram:GlobalID schemeID="${scheme}">1</ram:GlobalID></ram:ShipToTradeParty>` }));
    expect(verdict(shipTo("0088"), "BR-CL-26", "en16931")).toBe("success");
    expect(verdict(shipTo("GLN"), "BR-CL-26", "en16931")).toBe("error");
  });

  it("BR-CL-22 wants a VATEX exemption reason code, in any letter case", () => {
    const code = (c: string) => ubl(`<cac:TaxTotal><cac:TaxSubtotal><cac:TaxCategory><cbc:ID>E</cbc:ID><cbc:TaxExemptionReasonCode>${c}</cbc:TaxExemptionReasonCode>${vat}</cac:TaxCategory></cac:TaxSubtotal></cac:TaxTotal>`);
    expect(verdict(code("VATEX-EU-132-1F"), "BR-CL-22", "en16931")).toBe("success");
    expect(verdict(code("vatex-eu-ae"), "BR-CL-22", "en16931")).toBe("success");
    expect(verdict(code("VATEX-BE-123"), "BR-CL-22", "en16931")).toBe("error");
    const ciiCode = (c: string) => cii(ciiTx({ settlement: `<ram:ApplicableTradeTax><ram:TypeCode>VAT</ram:TypeCode><ram:CategoryCode>E</ram:CategoryCode><ram:ExemptionReasonCode>${c}</ram:ExemptionReasonCode></ram:ApplicableTradeTax>` }));
    expect(verdict(ciiCode("VATEX-FR-FRANCHISE"), "BR-CL-22", "en16931")).toBe("success");
    expect(verdict(ciiCode("EXEMPT"), "BR-CL-22", "en16931")).toBe("error");
  });
});

describe("Peppol's identifier formats for Norway, Denmark and Sweden (PEPPOL-COMMON-R041, R042, R049)", () => {
  /** How many findings the checker gives for one rule: the official rules report each element. */
  const count = (xml: string, rule: string, profile: ValidationProfile = "peppol") =>
    validateInvoiceXml(xml, profile).findings.filter((f) => f.ruleId === rule && f.severity === "error").length;
  /** The buyer with the same number as its address, party identifier and legal registration number. */
  const buyer = (scheme: string, id: string) =>
    ubl(`<cac:AccountingCustomerParty><cac:Party><cbc:EndpointID schemeID="${scheme}">${id}</cbc:EndpointID><cac:PartyIdentification><cbc:ID schemeID="${scheme}">${id}</cbc:ID></cac:PartyIdentification><cac:PartyLegalEntity><cbc:CompanyID schemeID="${scheme}">${id}</cbc:CompanyID></cac:PartyLegalEntity></cac:Party></cac:AccountingCustomerParty>`);
  const endpoint = (scheme: string, id: string) =>
    ubl(`<cac:AccountingCustomerParty><cac:Party><cbc:EndpointID schemeID="${scheme}">${id}</cbc:EndpointID></cac:Party></cac:AccountingCustomerParty>`);
  const ciiBuyer = (el: string) => cii(ciiContext() + ciiTx({ agreement: `<ram:BuyerTradeParty>${el}</ram:BuyerTradeParty>` }));

  it("R041: 9 digits with the mod-11 check digit, in every element that carries scheme 0192 (PEPPOL-COMMON-R041.xml, restated on invoices)", () => {
    // The official cases are Order documents; the same numbers in the same three elements of an invoice
    expect(count(buyer("0192", "991825827"), "PEPPOL-COMMON-R041")).toBe(0);
    expect(count(ubl('<cac:AccountingCustomerParty><cac:Party><cbc:EndpointID schemeID="0192">987654325</cbc:EndpointID><cac:PartyIdentification><cbc:ID schemeID="0192">123456785</cbc:ID></cac:PartyIdentification></cac:Party></cac:AccountingCustomerParty>'), "PEPPOL-COMMON-R041")).toBe(0);
    expect(count(buyer("0192", "991825822"), "PEPPOL-COMMON-R041")).toBe(3);
    expect(count(buyer("0192", "9918258222"), "PEPPOL-COMMON-R041")).toBe(3);
  });
  it("R041: the VAT form, spaces inside, all zeros and a remainder of 1 fail; spaces around the number don't", () => {
    for (const bad of ["NO991825827MVA", "991 825 827", "000000000", "100000130", "\u00a0991825827"])
      expect(verdict(endpoint("0192", bad), "PEPPOL-COMMON-R041"), JSON.stringify(bad)).toBe("error");
    expect(verdict(endpoint("0192", " 991825827\n"), "PEPPOL-COMMON-R041")).toBe("success");
  });
  it("R042: 8 digits or DK and 8 digits (PEPPOL-COMMON-R042.xml, UBL)", () => {
    const parties = (customer: string, supplier: string) =>
      ubl(`<cac:AccountingCustomerParty><cac:Party><cac:PartyLegalEntity><cbc:RegistrationName>Customer A A/S</cbc:RegistrationName><cbc:CompanyID schemeID="0184">${customer}</cbc:CompanyID></cac:PartyLegalEntity></cac:Party></cac:AccountingCustomerParty><cac:AccountingSupplierParty><cac:Party><cac:PartyLegalEntity><cbc:RegistrationName>Supplier A/S</cbc:RegistrationName><cbc:CompanyID schemeID="0184">${supplier}</cbc:CompanyID></cac:PartyLegalEntity></cac:Party></cac:AccountingSupplierParty>`);
    expect(count(parties("12345678", "DK12345678"), "PEPPOL-COMMON-R042")).toBe(0);
    expect(count(parties("1234567", "1234567"), "PEPPOL-COMMON-R042")).toBe(2);
  });
  it("R042 reads the text exactly as written: spaces or a line break around the number fail, unlike R041 and R049", () => {
    for (const bad of [" 12345678", "12345678\n", "DK 12345678", "dk12345678", "DK1234567", "DK123456789", "1234-5678"])
      expect(verdict(endpoint("0184", bad), "PEPPOL-COMMON-R042"), JSON.stringify(bad)).toBe("error");
    const f = validateInvoiceXml(endpoint("0184", " 12345678 "), "peppol").findings.find((x) => x.ruleId === "PEPPOL-COMMON-R042");
    expect(f?.message).toContain("spaces or line breaks around it");
  });
  it("R042 on CII: every URIID, ID and GlobalID with scheme 0184 (PEPPOL-COMMON-R042.xml, CII)", () => {
    expect(verdict(ciiBuyer('<ram:SpecifiedLegalOrganization><ram:ID schemeID="0184">DK12345678</ram:ID></ram:SpecifiedLegalOrganization>'), "PEPPOL-COMMON-R042")).toBe("success");
    expect(verdict(ciiBuyer('<ram:SpecifiedLegalOrganization><ram:ID schemeID="0184">345678</ram:ID></ram:SpecifiedLegalOrganization>'), "PEPPOL-COMMON-R042")).toBe("error");
    expect(verdict(ciiBuyer('<ram:GlobalID schemeID="0184">DK1234567X</ram:GlobalID>'), "PEPPOL-COMMON-R042")).toBe("error");
  });
  it("R049: 10 digits with the Luhn check digit (PEPPOL-COMMON-R049.xml, UBL)", () => {
    expect(verdict(endpoint("0007", "2021005489"), "PEPPOL-COMMON-R049")).toBe("success");
    expect(verdict(endpoint("0007", "556622-1100"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(endpoint("0007", "SE5566221100"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(endpoint("0007", "2021005480"), "PEPPOL-COMMON-R049")).toBe("error");
  });
  it("R049 on CII (PEPPOL-COMMON-R049.xml, CII), with spaces around it, the VAT form and full-width digits", () => {
    const uri = (id: string) => ciiBuyer(`<ram:URIUniversalCommunication><ram:URIID schemeID="0007">${id}</ram:URIID></ram:URIUniversalCommunication>`);
    expect(verdict(uri("2021005489"), "PEPPOL-COMMON-R049")).toBe("success");
    expect(verdict(uri("554433-2211"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(uri("SE5544332211"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(uri("2021005480"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(uri(" 2021005489 "), "PEPPOL-COMMON-R049")).toBe("success");
    expect(verdict(uri("SE202100548901"), "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(uri("２０２１００５４８９"), "PEPPOL-COMMON-R049")).toBe("error");
  });
  it("only identifiers with exactly that schemeID count, the item's standard ID doesn't, and EN 16931 alone checks none of them", () => {
    expect(verdict(endpoint(" 0192", "1"), "PEPPOL-COMMON-R041")).toBe("success");
    const item = ubl('<cac:InvoiceLine><cac:Item><cac:StandardItemIdentification><cbc:ID schemeID="0007">1</cbc:ID></cac:StandardItemIdentification></cac:Item></cac:InvoiceLine>');
    expect(verdict(item, "PEPPOL-COMMON-R049")).toBe("success");
    const payee = ubl('<cac:PayeeParty><cac:PartyLegalEntity><cbc:CompanyID schemeID="0007">556622-1100</cbc:CompanyID></cac:PartyLegalEntity></cac:PayeeParty>');
    expect(verdict(payee, "PEPPOL-COMMON-R049")).toBe("error");
    expect(verdict(payee, "PEPPOL-COMMON-R049", "en16931")).toBe("success");
    expect(verdict(buyer("0192", "991825822"), "PEPPOL-COMMON-R041", "en16931")).toBe("success");
    expect(verdict(endpoint("0184", "1234567"), "PEPPOL-COMMON-R042", "en16931")).toBe("success");
  });
});

describe("deliberate differences (src/content/official-parity.ts)", () => {
  it("BR-CO-09 accepts the Greek VAT prefix EL, which CEN 1.3.17 dropped by mistake (CEN issue 532)", () => {
    const seller = (vat: string) =>
      ubl(`<cac:AccountingSupplierParty><cac:Party><cac:PartyTaxScheme><cbc:CompanyID>${vat}</cbc:CompanyID><cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme></cac:PartyTaxScheme></cac:Party></cac:AccountingSupplierParty>`);
    expect(verdict(seller("EL094019245"), "BR-CO-09", "en16931")).toBe("success");
    expect(verdict(seller("GR094019245"), "BR-CO-09", "en16931")).toBe("success");
    expect(verdict(seller("ZZ094019245"), "BR-CO-09", "en16931")).toBe("error");
    const ciiSeller = (scheme: string, vat: string) =>
      cii(`${ciiContext()}${ciiTx({ agreement: `<ram:SellerTradeParty><ram:SpecifiedTaxRegistration><ram:ID schemeID="${scheme}">${vat}</ram:ID></ram:SpecifiedTaxRegistration></ram:SellerTradeParty>` })}`);
    expect(verdict(ciiSeller("VA", "EL094019245"), "BR-CO-09", "en16931")).toBe("success");
    // CII reads only schemeID "VA" as a VAT number: another scheme isn't checked for a prefix
    expect(verdict(ciiSeller("VA", "094019245"), "BR-CO-09", "en16931")).toBe("error");
    expect(verdict(ciiSeller("FC", "094019245"), "BR-CO-09", "en16931")).toBe("success");
  });
});
